local a={}a.FLIGHT_MS=250;a.PARAMS_MS=1000;local function b(c,d)if type(c)~="number"then return"-"end;return tostring(math.floor(c*d+0.5))end;function a.sigPfd(e)e=e or{}local f=e.target;return table.concat({b(e.pitch,100),b(e.roll,100),b(e.heading,1),b(e.altitude,10),b(e.gpsAlt,10),b(e.tas,10),b(e.sas,10),tostring(e.gpsFixOk),b(f and f.bearing,1),b(f and f.relBearing,1),b(f and f.distanceH,1),b(f and f.altDelta,1),tostring(f and f.name or"-"),tostring(f and f.color or"-")},"|")end;function a.sigFlight(e)e=e or{}return table.concat({b(e.pumpAmount,1),b(e.tankMb,1),tostring(e.feeding),tostring(e.engaged),tostring(e.gndSafety),tostring(e.flightMode),tostring(e.engineMaster),tostring(e.pulses),tostring(e.fcsStale),e.fcsStale and tostring(e.blinkPhase)or"-",tostring(e.fuel),tostring(e.fuelPct),tostring(e.badFuel),tostring(e.fuelEst and e.fuelEst.state),b(e.fuelEst and e.fuelEst.mbPerMin,1),b(e.fuelEst and e.fuelEst.secondsLeft,1)},"|")end;function a.sigParams(e)e=e or{}local g=e.comAuto;return table.concat({tostring(e.engineMaster),tostring(e.onGround),tostring(e.gndSafety),b(e.vSpeed,100),b(e.tankFrac,100),tostring(e.engaged),tostring(e.flightMode),tostring(g and g.phase or"-"),tostring(g and g.captured~=nil),tostring(e.uiRev)},"|")end;local h={flight=true,emc=true,fcs=true}function a.policyFor(i,j)if i=="pfd"then return{mode="rate",ms=j,sig=a.sigPfd}end;if h[i]then return{mode="rate",ms=a.FLIGHT_MS,sig=a.sigFlight}end;if i=="tuning"then return{mode="rate",ms=a.PARAMS_MS,sig=a.sigParams}end;return{mode="event"}end;return a